from qa import *
from playwright.sync_api import sync_playwright
e = Ev("CP-07"); e.w("CP-07", time.strftime("%Y-%m-%d %H:%M"))
TM1 = login("qa_medico1"); EXA2 = IDS["EX_A2"]; DOCA2 = IDS["DOC_A2"]
a0 = sql("select coalesce(max(id),0) from auditoria").split("\n")[2].strip(); e.w("último id auditoría inicial:",a0)
def mui(pg,name,opt): pg.locator(f"[name={name}]").locator("xpath=..").click(); pg.get_by_role("option",name=opt).first.click()
with sync_playwright() as p:
    b=p.chromium.launch(); pg=b.new_page(); pg.set_viewport_size({"width":1500,"height":1100})
    dl=[]; pg.on("dialog", lambda d:(dl.append(d.message), d.accept()))
    pg.on("response", lambda r: e.w("  respuesta UI:",r.status,r.request.method,r.url,r.text()[:160]) if r.request.method in("POST","PUT","DELETE") else None)
    pg.goto(WEB+"/login"); pg.get_by_label("Nombre de usuario").fill("qa_medico1"); pg.get_by_label("Contraseña").fill(PW["qa_medico1"]); pg.get_by_role("button",name="Entrar").click(); pg.wait_for_url("**/home",timeout=15000)
    e.step(1,"UI Nuevo Examen"); pg.goto(WEB+"/examenes"); pg.get_by_role("tab",name="Nuevo Examen").click(); pg.wait_for_timeout(8000)
    mui(pg,"tipo_examen_medico_id","Hemograma completo"); mui(pg,"paciente_id","Juan Pérez")
    pg.fill("[name=diagnosis]","Anemia leve (dato sintético)"); pg.fill("[name=tratamiento]","Suplemento de hierro"); pg.fill("[name=observaciones]","Control en 30 días")
    pg.screenshot(path=os.path.join(EVD,"CP-07_paso1_form.png")); pg.get_by_role("button",name="Crear Examen").click(); pg.wait_for_timeout(8000)
    e.w("toasts:",pg.locator("[data-sonner-toast]").all_inner_texts())
    e.w(sql("select id,tipo_examen_medico_id,paciente_id,diagnosis,tratamiento,created_at from examen_medico order by id desc limit 1"))
    e.step(2,"API POST /examenes y sin campos")
    body={"tipo_examen_medico_id":1,"paciente_id":1,"diagnosis":"Anemia leve (dato sintético)","tratamiento":"Suplemento de hierro","observaciones":"Control en 30 días"}
    r=api("POST","/examenes",token=TM1,body=body); e.w("completo:",short(r,250))
    r=api("POST","/examenes",token=TM1,body={k:v for k,v in body.items() if k!="paciente_id"}); e.w("sin paciente_id:",short(r,250))
    r=api("POST","/examenes",token=TM1,body={k:v for k,v in body.items() if k!="tipo_examen_medico_id"}); e.w("sin tipo_examen_medico_id:",short(r,250))
    e.step(3,"PAC_A Mis Resultados"); pg2=b.new_page(); pg2.set_viewport_size({"width":1500,"height":1100})
    pg2.goto(WEB+"/login"); pg2.get_by_label("Nombre de usuario").fill("paciente"); pg2.get_by_label("Contraseña").fill(PW["paciente"]); pg2.get_by_role("button",name="Entrar").click(); pg2.wait_for_url("**/home",timeout=15000)
    pg2.goto(WEB+"/mis-resultados"); pg2.wait_for_timeout(8000); t=pg2.inner_text("body"); e.w("¿aparece 'Anemia leve (dato sintético)'?", "Anemia leve (dato sintético)" in t, "| cantidad de ocurrencias:", t.count("Anemia leve (dato sintético)")); pg2.screenshot(path=os.path.join(EVD,"CP-07_paso3_mis_resultados.png"))
    e.step(4,"UI editar EX_A2 y reemplazar documento"); pg.goto(WEB+f"/examenes?edit={EXA2}"); pg.wait_for_timeout(9000)
    pg.fill("[name=diagnosis]","Anemia leve resuelta"); pg.fill("[name=tratamiento]","Alta médica"); pg.screenshot(path=os.path.join(EVD,"CP-07_paso4_editar.png"))
    pg.get_by_role("button",name="Actualizar Examen").click(); pg.wait_for_timeout(8000); e.w("toasts edición:",pg.locator("[data-sonner-toast]").all_inner_texts())
    e.w(sql(f"select id,diagnosis,tratamiento from examen_medico where id={EXA2}"))
    pg.goto(WEB+f"/examenes?edit={EXA2}"); pg.wait_for_timeout(9000)
    e.w("documentos listados en el formulario:",pg.locator("text=/resultado_examen.*pdf/").all_inner_texts())
    e.w("Intento de reemplazo: eliminar DOC_A2 con el botón del formulario (MED1)")
    pg.get_by_role("button",name="Eliminar resultado_examen_v1.pdf").click(); pg.wait_for_timeout(4000); e.w("diálogo confirm:",dl); e.w("toasts:",pg.locator("[data-sonner-toast]").all_inner_texts())
    e.w("Subir resultado_examen_v2.pdf al examen"); pg.locator("input[type=file]").set_input_files(DAT+"/resultado_examen_v2.pdf"); pg.wait_for_timeout(9000); e.w("toasts:",pg.locator("[data-sonner-toast]").all_inner_texts()); pg.screenshot(path=os.path.join(EVD,"CP-07_paso4_tras_subir_v2.png"))
    b.close()
e.step(5,"descargar documentos vigentes de EX_A2")
r=api("GET",f"/documentos/examen/{EXA2}",token=TM1); e.w(short(r,300)); docs=r.json()
for d in docs:
    x=api("GET",f"/documentos/{d['id']}",token=TM1); h=sha_b(x.content); e.w(f"doc id {d['id']} {d['nombre_archivo']}: HTTP {x.status_code} SHA-256 {h}", "= v2" if h==sha(DAT+'/resultado_examen_v2.pdf') else "= v1" if h==sha(DAT+'/resultado_examen_v1.pdf') else "(otro)")
e.w("SHA-256 v1:",sha(DAT+"/resultado_examen_v1.pdf"),"| v2:",sha(DAT+"/resultado_examen_v2.pdf"))
e.step(6,"auditoría"); e.w(sql(f"select id,usuario_id,accion from auditoria where id>{a0} order by id"))
